+package com.example.service;
+
+import org.apache.http.client.config.RequestConfig;
+import org.apache.http.client.methods.CloseableHttpResponse;
+import org.apache.http.client.methods.HttpGet;
+import org.apache.http.impl.client.CloseableHttpClient;
+import org.apache.http.impl.client.HttpClients;
+import org.apache.http.util.EntityUtils;
+
+import java.io.IOException;
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+
+/**
+ * Service for fetching content from URLs.
+ */
+public class UrlService {
+
+    private static final int CONNECT_TIMEOUT_MS = 5000;
+    private static final int READ_TIMEOUT_MS = 5000;
+
+    private final RequestConfig requestConfig;
+
+    public UrlService() {
+        this.requestConfig = RequestConfig.custom()
+                .setConnectTimeout(CONNECT_TIMEOUT_MS)
+                .setSocketTimeout(READ_TIMEOUT_MS)
+                .setConnectionRequestTimeout(CONNECT_TIMEOUT_MS)
+                .build();
+    }
+
+    /**
+     * Fetches the content of the given URL and returns the response body as a string.
+     *
+     * @param userUrl the URL to fetch (must not be null or empty, must use HTTP or HTTPS)
+     * @return the response body as a string
+     * @throws IllegalArgumentException if the URL is invalid or uses an unsupported protocol
+     * @throws SecurityException        if the URL points to a private or internal network address
+     * @throws RuntimeException         if the HTTP request fails
+     */
+    public String fetchUrlContent(String userUrl) {
+        if (userUrl == null || userUrl.trim().isEmpty()) {
+            throw new IllegalArgumentException("URL must not be null or empty");
+        }
+
+        URI uri = parseUrl(userUrl);
+        validateScheme(uri);
+        validateHostNotInternal(uri);
+
+        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
+            HttpGet httpGet = new HttpGet(uri);
+            httpGet.setConfig(requestConfig);
+
+            try (CloseableHttpResponse response = httpClient.execute(httpGet)) {
+                int statusCode = response.getStatusLine().getStatusCode();
+                if (statusCode < 200 || statusCode >= 300) {
+                    throw new IOException("Server returned HTTP status " + statusCode);
+                }
+                return EntityUtils.toString(response.getEntity());
+            }
+        } catch (IOException e) {
+            throw new RuntimeException("Failed to fetch URL content from: " + userUrl, e);
+        }
+    }
+
+    private static URI parseUrl(String userUrl) {
+        try {
+            return new URI(userUrl);
+        } catch (URISyntaxException e) {
+            throw new IllegalArgumentException("Malformed URL: " + userUrl, e);
+        }
+    }
+
+    private static void validateScheme(URI uri) {
+        String scheme = uri.getScheme();
+        if (scheme == null || (!"http".equalsIgnoreCase(scheme) && !"https".equalsIgnoreCase(scheme))) {
+            throw new IllegalArgumentException("Only HTTP and HTTPS URLs are supported");
+        }
+    }
+
+    private static void validateHostNotInternal(URI uri) {
+        String host = uri.getHost();
+        if (host == null || host.isEmpty()) {
+            throw new IllegalArgumentException("URL must contain a valid host");
+        }
+
+        try {
+            InetAddress address = InetAddress.getByName(host);
+            if (address.isLoopbackAddress()
+                    || address.isSiteLocalAddress()
+                    || address.isLinkLocalAddress()
+                    || address.isAnyLocalAddress()) {
+                throw new SecurityException("Access to internal or private network addresses is not allowed");
+            }
+        } catch (UnknownHostException e) {
+            throw new IllegalArgumentException("Unable to resolve host: " + host, e);
+        }
+    }
+}
